<section class="card panel orders"><div class="head"><div><h2>Pesanan Terbaru Masuk</h2><p>Transaksi terbaru dari pelanggan toko.</p></div><a class="detail" href="<?= base_url('/admin/transaksi') ?>">Lihat semua →</a></div><?php if($recent_orders): ?><div class="table"><table><thead><tr><th>Invoice & Pelanggan</th><th>Lokasi</th><th>Total Nilai</th><th>Status</th><th>Tanggal</th><th></th></tr></thead><tbody><?php foreach($recent_orders as $o): $badge=$statuses[$o['status']]??['Tidak diketahui','amber']; ?><tr><td><div class="invoice">#<?= esc($o['invoice_number']) ?></div><div class="sub"><?= esc($o['nama_penerima']?:($o['user_nama']??'Pelanggan')) ?></div></td><td><?= esc($o['kota']?:'-') ?></td><td><strong>Rp <?= number_format($o['total'],0,',','.') ?></strong></td><td><span class="badge <?= $badge[1] ?>"><?= esc($badge[0]) ?></span></td><td><?= esc(date('d M Y',strtotime($o['created_at']))) ?></td><td><a class="detail" href="<?= base_url('/admin/transaksi/'.$o['id']) ?>">Detail</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty"><span class="material-symbols-rounded" style="font-size:38px">receipt_long</span><br>Belum ada transaksi terbaru.</div><?php endif; ?></section></main></div></div>
<script>const c=document.getElementById('revenueChart');if(c)new Chart(c,{type:'pie',data:{labels:<?= json_encode($labels, JSON_UNESCAPED_UNICODE) ?>,datasets:[{data:<?= json_encode($values) ?>,backgroundColor:['#c85a32','#687e65','#d8a74e','#6587a8','#9c74a8','#d77979','#7ca5a1','#b58b67'],borderColor:'#fcf9f4',borderWidth:3}]},options:{maintainAspectRatio:false,plugins:{legend:{position:'right',labels:{color:'#695d55',padding:14,font:{size:10}}},tooltip:{callbacks:{label:x=>x.label+': Rp '+Number(x.raw).toLocaleString('id-ID')}}}}});</script></body></html>
